mapper.select:
select statement_cash_flow.*
from statement_cash_flow
where statement_cash_flow.deleted = 'n'
and statement_cash_flow.book_id = #{params.bookId}

    AND YEAR(statement_cash_flow.report_date) = #{params.year}


    AND MONTH(statement_cash_flow.report_date) = #{params.month}


    AND QUARTER(statement_cash_flow.report_date) = #{params.quarter}

SELECT v.word, jvicf.*, i.id as voucherItemId, v.voucher_date as voucherDate, i.summary as summary, i.subject_name as subjectName, i.debit_amount as debitAmount, i.credit_amount as creditAmount, v.id as voucherId FROM voucher_item_cash_flow jvicf JOIN voucher_item i on jvicf.voucher_item_id = i.id and jvicf.book_id = #{params.bookId} JOIN voucher v ON i.voucher_id = v.id WHERE i.deleted = 'n' AND v.deleted = 'n' AND v.book_id = #{params.bookId} AND v.sender_id IS NOT NULL AND v.sender_id <> ''
AND YEAR(i.voucher_date) = #{params.year}
AND MONTH(i.voucher_date) = #{params.month}
AND QUARTER(i.voucher_date) = #{params.quarter}

SELECT v.word, jvicf.*, i.id as voucherItemId, v.voucher_date as voucherDate, i.summary as summary, i.subject_name as subjectName, i.debit_amount as debitAmount, i.credit_amount as creditAmount, v.id as voucherId FROM voucher_item_cash_flow jvicf JOIN voucher_item i on jvicf.voucher_item_id = i.id and jvicf.book_id = #{params.bookId} JOIN voucher v ON i.voucher_id = v.id WHERE i.deleted = 'n' AND v.deleted = 'n' AND v.book_id = #{params.bookId} AND v.sender_id IS NOT NULL AND v.sender_id <> ''
AND YEAR(i.voucher_date) = #{params.year}
AND MONTH(i.voucher_date) <= #{params.endMonth}
AND MONTH(i.voucher_date) <= (#{params.endQuarter} * 3)
